// Generated by `cargo run -p bindings-gen`. Do not edit by hand.
// Owner of GeoPoint, the one lon/lat point type (single-lonlat-point-type, ADR 0028; §18 F39).
// Invariant: no other module declares a {lon, lat} or [lon, lat] point type.
// This file has been generated by Specta. Do not edit this file manually.
// Offset along a split sheet's page axes from its split pivot (`2.1-M161`).
export type AlongPageM = {
	// Distance right along the page axis in metres.
	right_m: number,
	// Distance down along the page axis in metres.
	down_m: number,
};

// One named input of an analysis bound to a library item.
export type AnalysisInputBinding = {
	key: string,
	item_id: string,
};

// State of one analysis job.
export type AnalysisJobState = "Preparing" | "Complete" | "Failed" | "Cancelled";

// One registered analysis this item could feed, or why it cannot.
export type AnalysisOffer = {
	analysis_id: string,
	// `None` when the analysis can run on this item.
	unavailable: AnalysisUnavailable | null,
};

export type AnalysisParamValue = {
	key: string,
	value: ParamValue,
};

// Receipt for one created definition or one rerun.
export type AnalysisReceipt = {
	definition_id: string,
	job_id: string,
	// The derived items the definition publishes, in registry output order.
	item_ids: string[],
};

// A request to run a registered analysis as a new definition.
export type AnalysisRequest = {
	// Registry id, e.g. `terrain.slope`.
	analysis_id: string,
	inputs: AnalysisInputBinding[],
	/**
	 *  Omitted parameters take their registry default; a parameter without a
	 *  default must be given.
	 */
	parameters: AnalysisParamValue[],
	// Keys of the outputs to produce; required outputs are always produced.
	outputs: string[],
	// The name to publish the results under; blank publishes unnamed items.
	name: string | null,
};

// The latest job of a derived item's definition.
export type AnalysisRunStatus = {
	job_id: string,
	state: AnalysisJobState,
	message: string | null,
};

/**
 *  Why an analysis cannot run on an item. Only reasons that need the
 *  catalogue, stored grid facts or the engine are native; the frontend adds
 *  its own (Web edition, already in Layers).
 */
export type AnalysisUnavailable =
// The item is not a type the analysis accepts.
{ reason: "WrongInput"; expected: LibraryItemType[] } |
// The item has no published data yet.
{ reason: "NotReady" } |
// The analysis needs values in metres.
{ reason: "ValuesNotMetres"; units: string } |
// The analysis needs a projected grid in ground metres, not Web Mercator.
{ reason: "GridNotProjectedMetres" } |
// The engine the analysis runs on is not installed.
{ reason: "EngineMissing"; detail: string };

